		String c1 = fetchOwner(createOwnerOk(withPostcode(ownerNode()))).get("customerCode").asText();
		String c2 = fetchOwner(createOwnerOk(withPostcode(ownerNode()))).get("customerCode").asText();
		assertNotEquals(c1, c2);
	}
